  s+=`<path class="${C}" d="M686 240H712V6H608V78"/>`;
  s+=`<path d="M660 90V146H626" stroke="var(--fg)" stroke-width="1.6" fill="none"/>`;
  if(on)s+=vtag(372,46,'y='+fm(v.y,2))+vtag(36,92,'w='+fm(v.w,2),'start')+vtag(640,268,'x='+fm(v.x,2));
